// List uncovered statement lines per file from Istanbul coverage-final.json.
const fs = require('fs');
const cov = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const want = process.argv[3];
const keys = Object.keys(cov).filter(k => k.endsWith(want));
if (keys.length === 0) { console.log('NO COVERAGE ENTRY for ' + want); process.exit(0); }
for (const key of keys) {
  const e = cov[key];
  console.log('== ' + key);
  const unc = [];
  for (const id in e.s) {
    if (e.s[id] === 0) {
      const sl = e.statementMap[id];
      unc.push(sl.start.line + (sl.end.line !== sl.start.line ? '-' + sl.end.line : ''));
    }
  }
  // group consecutive
  const lines = [...new Set(unc.map(Number))].sort((a, b) => a - b);
  const parts = [];
  let start = null, prev = null;
  for (const l of lines) {
    if (start === null) { start = prev = l; continue; }
    if (l === prev + 1) { prev = l; continue; }
    parts.push(start === prev ? String(start) : start + '-' + prev);
    start = prev = l;
  }
  if (start !== null) parts.push(start === prev ? String(start) : start + '-' + prev);
  console.log('uncovered statement lines: ' + (parts.join(', ') || '(none)'));
  console.log('statements: ' + Object.keys(e.s).length + ', uncovered: ' + lines.length);
  const ub = [];
  for (const id in e.b) {
    e.b[id].forEach((h, i) => { if (h === 0) ub.push(e.branchMap[id].locations[i].start.line + '(' + (e.branchMap[id].type) + ' path' + i + ')'); });
  }
  console.log('uncovered branch paths: ' + (ub.length ? ub.join(', ') : '(none)'));
}

